import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long k = Long.parseLong(next());
        String[][] ops = new String[(int) n][2];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = next();
            }
        }

        int cap = (int) k;
        long[] buf = new long[cap];
        int head = 0, size = 0;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            String op = ops[i][0];
            if (op.equals("enQueue")) {
                if (size == cap) {
                    sb.append("no\n");
                } else {
                    buf[(head + size) % cap] = Long.parseLong(ops[i][1]);
                    size++;
                    sb.append("yes\n");
                }
            } else if (op.equals("deQueue")) {
                if (size == 0) {
                    sb.append("no\n");
                } else {
                    head = (head + 1) % cap;
                    size--;
                    sb.append("yes\n");
                }
            } else if (op.equals("Front")) {
                sb.append(size > 0 ? buf[head] : -1).append("\n");
            } else if (op.equals("Rear")) {
                sb.append(size > 0 ? buf[(head + size - 1) % cap] : -1).append("\n");
            } else if (op.equals("isEmpty")) {
                sb.append(size == 0 ? "yes" : "no").append("\n");
            } else {
                sb.append(size == cap ? "yes" : "no").append("\n");
            }
        }
        System.out.print(sb);
    }
}
